import csv
import io


def parse_csv(raw_csv: str):
    stream = io.StringIO(raw_csv.removeprefix("\ufeff"), newline="")

    # Skip the leading comment preamble before interpreting CSV quoting.
    while True:
        position = stream.tell()
        line = stream.readline()
        if not line:
            return {"columns": [], "rows": []}
        if line.lstrip().startswith("#") or not line.strip():
            continue
        stream.seek(position)
        break

    reader = csv.reader(stream, delimiter=",", quotechar='"', doublequote=True)
    columns = next(reader, None)
    if columns is None:
        return {"columns": [], "rows": []}

    rows = list(reader)
    width = max(4, len(columns), max((len(row) for row in rows), default=0))
    used_names = set(columns)

    while len(columns) < width:
        base = f"extra_{len(columns) + 1}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
